package db

import (
	"database/sql"
)

type Todo struct {
	ID        int    `json:"id"`
	Title   string `json:"title"`
	Completed bool `json:"completed"`
}

func (d *Database) CreateTodo(title string, completed bool) (*Todo, error) {
	var id int
	err := d.db.QueryRow(`INSERT INTO todos (title, completed) VALUES (?, ?) returning id`, title, completed).Scan(&id)
	if err != nil {
		return nil, err
	}
	return &Todo{ID: id, Title: title, Completed: completed}, nil
}

func (d *Database) GetTodo(id int) (*Todo, error) {
	var todo Todo
	err := d.db.QueryRow(`SELECT id, title, completed FROM todos WHERE id = ?`, id).Scan(&todo.ID, &todo.Title, &todo.Completed)
	if err != nil {
		return nil, err
	}
	return &todo, nil
}

func (d *Database) ListTodos() ([]*Todo, error) {
	var todos []*Todo
	rows, err := d.db.Query(`SELECT id, title, completed FROM todos`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var todo Todo
		err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed)
		if err != nil {
			return nil, err
		}
		todos = append(todos, &todo)
	}
	return todos, nil
}

func (d *Database) UpdateTodo(id int, title string, completed bool) (*Todo, error) {
	var updated Todo
	err := d.db.QueryRow(`UPDATE todos SET title = ?, completed = ? WHERE id = ? returning id, title, completed`, title, completed, id).Scan(&updated.ID, &updated.Title, &updated.Completed)
	if err != nil {
		return nil, err
	}
	return &updated, nil
}

func (d *Database) DeleteTodo(id int) error {
	_,DB.Exec(`DELETE FROM todos WHERE id = ?`, id)
	return nil
}

