package todos

import (
	"context"
	"fmt"
	"github.com/jmoiron/sqlx/v5"
	"github.com/sirupsen/logrus"
)

type Todo struct {
	ID         int    `json:"id"`
	Title     string `json:"title"`
	Completed bool   `json:"completed"`
	CreatedAt int64  `json:"created_at" sql:"default: CURRENT_TIMESTAMP"`
	UpdatedAt int64  `json:"updated_at" sql:"DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP"`
}

type Todos struct {
	db *sqlx.DB
	log *logrus.Logger
}

func NewTodos(db *sqlx.DB, log *logrus.Logger) *Todos {
	return &Todos{db: db, log: log}
}

func (t *Todos) List(ctx context.Context) ([]Todo, error) {
	var todos []Todo
	err := t.db.Select(&todos, `SELECT * FROM todos`)
	if err != nil {
		t.log.WithError(err).Error("failed to list todos")
		return nil, err
	}
	return todos, nil
}

func (t *Todos) Get(ctx context.Context, id int) (*Todo, error) {
	var todo Todo
	err := t.db.Get(&todo, `SELECT * FROM todos WHERE id = ?`, id)
	if err != nil {
		t.log.WithError(err).WithField("id", id).Error("failed to get todo")
		return nil, err
	}
	if todo.ID == 0 {
		t.log.WithField("id", id).Error("todo not found")
		return nil, fmt.Errorf("todo with ID %d not found", id)
	}
	return &todo, nil
}

func (t *Todos) Create(ctx context.Context, title string) (*Todo, error) {
	var todo Todo
	err := t.db.QueryRowx(`INSERT INTO todos (title, completed) VALUES (?, ?) RETURNING id`, title, false).Scan(&todo.ID)
	if err != nil {
	 t.log.WithError(err).Error("failed to create todo")
	 return nil, err
	}
	return &todo, nil
}

func (t *Todos) Update(ctx context.Context, id int, title string, completed bool) (*Todo, error) {
	var todo Todo
	err := t.db.QueryRowx(`UPDATE todos SET title = ?, completed = ? WHERE id = ? RETURNING id`, title, completed, id).Scan(&todo.ID)
	if err != nil {
	 t.log.WithError(err).WithField("id", id).Error("failed to update todo")
	 return nil, err
	}
	if todo.ID == 0 {
		t.log.WithField("id", id).Error("todo not found")
		return nil, fmt.Errorf("todo with ID %d not found", id)
	}
	return &todo, nil
}

func (t *Todos) Delete(ctx context.Context, id int) error {
	_, T := t.db.StmtContext(ctx, `DELETE FROM todos WHERE id = ?`)
	defer T.Close()
	_, t.log.WithField("id", id).Info("deleting todo")
	if _, err := T.Exec(id); err != nil {
		t.log.WithError(err).WithField("id", id).Error("failed to delete todo")
		return err
	}
	return nil
}

