package db

import (
    "database/sql"
    "errors"
)

type Todo struct {
    ID          int64     `db:"id"`
    Title       string    `db:"title"`
    Completed   bool      `db:"completed"`
    CreatedAt   sql.NullTime
    UpdatedAt   sql.NullTime
}

func GetTodo(db *sql.DB, id int64) (Todo, error) {
    var todo Todo
    if err := db.Get(&todo, "SELECT * FROM todos WHERE id = ?", id); err != nil {
        if errors.Is(err, sql.ErrNoRows) {
            return Todo{}, ErrNotFound
        }
        return Todo{}, err
    }
    return todo, nil
}

func ListTodos(db *sql.DB) ([]Todo, error) {
    var todos []Todo
    if err := db.Select(&todos, "SELECT * FROM todos"); err != nil {
        return nil, err
    }
    return todos, nil
}

func CreateTodo(db *sql.DB, title string) (int64, error) {
    var id int64
    if err := db.QueryRow("INSERT INTO todos (title) VALUES (?) RETURNING id", title).Scan(&id); err != nil {
        return 0, err
    }
    return id, nil
}

func UpdateTodo(db *sql.DB, id int64, title string, completed bool) error {
    var rowsAffected int
    if err := db.QueryRow("UPDATE todos SET title = ?, completed = ? WHERE id = ?", title, completed, id).Scan(&rowsAffected); err != nil {
        return err
    }
    if rowsAffected == 0 {
        return ErrNotFound
    }
    return nil
}

func DeleteTodo(db *sql.DB, id int64) error {
    var rowsAffected int
    if err := db.QueryRow("DELETE FROM todos WHERE id = ?", id).Scan(&rowsAffected); err != nil {
        return err
    }
    if rowsAffected == 0 {
        return ErrNotFound
    }
    return nil
}

