	db, err := sql.Open("postgres", "user=your_user dbname=your_db sslmode=disable")
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()

	todo := &Todo{Title: "test todo"}
	err = todo.Create(db, "test title")
	if err != nil {
		t.Fatal(err)
	}
	defer todo.Delete(db)

	resultTodo, err := GetTodo(db, todo.ID)
	if err != nil {
		t.Fatal(err)
	}
	if resultTodo.Title != "test title" {
		t.Errorf("Title mismatch: expected 'test title', got '%s'", resultTodo.Title)
	}
}

