	db, err := sql.Open("postgres", "user=your_user dbname=your_db sslmode=disable")
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()

	todo := &Todo{Title: "test todo"}
	err = todo.Create(db, "test title")
	if err != nil {
		t.Fatal(err)
	}
	defer todo.Delete(db)

	err = todo.Update(db, "updated title", true)
	if err != nil {
		t.Fatal(err)
	}

	resultTodo, err := GetTodo(db, todo.ID)
	if err != nil {
		t.Fatal(err)
	}
	if resultTodo.Title != "updated title" || !resultTodo.Completed {
		t.Errorf("Update mismatch: expected 'updated title' and true, got '%s', %v", resultTodo.Title, resultTodo.Completed)
