package db

import (
	"database/sql"
)

type Todo struct {
	ID        int    `db:"id"`
	Title     string `db:"title"`
	Completed bool   `db:"completed"`
	CreatedAt sql.NullTime
	UpdatedAt sql.NullTime
}

func (t *Todo) Create(db *sql.DB) error {
	query := "INSERT INTO todos (title, completed) VALUES ($1, $2) RETURNING id"
	return db.QueryRow(query, t.Title, t.Completed).Scan(&t.ID)
}

func (t *Todo) GetAll(db *sql.DB) ([]*Todo, error) {
	var todos []*Todo
	query := "SELECT id, title, completed, created_at, updated_at FROM todos"
	rows, err := db.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	for rows.Next() {
		var todo Todo
		if err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt); err != nil {
			return nil, err
		}
		todos = append(todos, &todo)
	}
	return todos, nil
}

func (t *Todo) Get(db *sql.DB) error {
	query := "SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = $1"
	return db.QueryRow(query, t.ID).Scan(&t.ID, &t.Title, &t.Completed, &t.CreatedAt, &t.UpdatedAt)
}

func (t *Todo) Update(db *sql.DB) error {
	query := "UPDATE todos SET title = $1, completed = $2, updated_at = NOW() WHERE id = $3"
	_, err := db.Exec(query, t.Title, t.Completed, t.ID)
	return err
}

func (t *Todo) Delete(db *sql.DB) error {
	query := "DELETE FROM todos WHERE id = $1"
	_, err := db.Exec(query, t.ID)
	return err
}

