package db

import (
	"database/sql"
	"log"
)

type Todo struct {
	ID        int64
	Title     string
	Completed bool
	CreatedAt sql.NullTime
	UpdatedAt sql.NullTime
}

func (t *Todo) Create(db *sql.DB, title string, completed bool) error {
	return db.QueryRow(`
		INSERT INTO todos (title, completed)
		VALUES ($1, $2)
		RETURNING id, title, completed, created_at, updated_at
	`, title, completed).Scan(&t.ID, &t.Title, &t.Completed, &t.CreatedAt, &t.UpdatedAt)
}

func (t *Todo) Get(db *sql.DB, id int64) error {
	return db.QueryRow(`
		SELECT id, title, completed, created_at, updated_at
		FROM todos
		WHERE id = $1
	`, id).Scan(&t.ID, &t.Title, &t.Completed, &t.CreatedAt, &t.UpdatedAt)
}

func (t *Todo) Update(db *sql.DB, id int64, title string, completed bool) error {
	return db.QueryRow(`
		UPDATE todos
		SET title = $2, completed = $3
		WHERE id = $1
		RETURNING id, title, completed, created_at, updated_at
	`, id, title, completed).Scan(&t.ID, &t.Title, &t.Completed, &t.CreatedAt, &t.UpdatedAt)
}

func (t *Todo) Delete(db *sql.DB, id int64) error {
	_, err := db.Exec(`
		DELETE FROM todos
		WHERE id = $1
	`, id)
	return err
}

func (t *Todo) List(db *sql.DB, completed bool) ([]*Todo, error) {
	rows, err := db.Query(`
		SELECT id, title, completed, created_at, updated_at
		FROM todos
		WHERE completed = $1
	`, completed)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var todos []*Todo
	for rows.Next() {
		var todo Todo
		if err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt); err != nil {
			return nil, err
		}
		todos = append(todos, &todo)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	return todos, nil
}

