	Completed bool      `json:"completed"`
	CreatedAt string    `json:"created_at"`
	UpdatedAt string    `json:"updated_at"`
}

func ListTodos(c *gin.Context) {
	db, ok := c.Get("db")
	if !ok {
		log.Error().Msg("database connection not found")
		c.Status(http.StatusInternalServerError)
		return
	}

	rows, err := db.(*sqlx.DB).Query(listTodosSQL)
	if err != nil {
		log.Error().Err(err).Msg("failed to list todos")
		c.Status(http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		if err := rows.StructScan(&todo); err != nil {
			log.Error().Err(err).Msg("failed to scan todo")
			c.Status(http.StatusInternalServerError)
			return
		}
		todos = append(todos, todo)
	}

	if err := rows.Err(); err != nil {
		log.Error().Err(err).Msg("error iterating over rows")
		c.Status(http.StatusInternalServerError)
		return
	}

	c.JSON(http.StatusOK, todos)
}

func GetTodo(c *gin.Context) {
	db, ok := c.Get("db")
	if !ok {
		log.Error().Msg("database connection not found")
		c.Status(http.StatusInternalServerError)
		return
	}

	id := c.Param("id")

	var todo Todo
	err := db.(*sqlx.DB).Get(&todo, getTodoSQL, id)
	if err != nil {
		log.Error().Err(err).Msg("failed to get todo")
		c.Status(http.StatusInternalServerError)
		return
	}

	c.JSON(http.StatusOK, todo)
}

func CreateTodo(c *gin.Context) {
	var todo Todo
	if err := c.ShouldBindJSON(&todo); err != nil {
		log.Error().Err(err).Msg("failed to bind JSON")
		c.StatusBadRequest()
		return
	}

	db, ok := c.Get("db")
	if !ok {
		log.Error().Msg("database connection not found")
		c.Status(http.StatusInternalServerError)
		return
	}

	var newTodo Todo
	err = db.(*sqlx.DB).QueryRow(createTodoSQL, todo.Title, todo.Completed).StructScan(&newTodo)
	if err != nil {
		log.Error().Err(err).Msg("failed to create todo")
		c.Status(http.StatusInternalServerError)
		return
	}

	c.JSON(http.StatusCreated, newTodo)
}

func UpdateTodo(c *gin.Context) {
	id := c.Param("id")

	var todo Todo
	if err := c.ShouldBindJSON(&todo); err != nil {
		log.Error().Err(err).Msg("failed to bind JSON")
		c.StatusBadRequest()
		return
	}

	db, ok := c.Get("db")
	if !ok {
		log.Error().Msg("database connection not found")
		c.Status(http.StatusInternalServerError)
		return
	}

	var updatedTodo Todo
	err = db.(*sqlx.DB).QueryRow(updateTodoSQL, id, todo.Title, todo.Completed).StructScan(&updatedTodo)
	if err != nil {
		log.Error().Err(err).Msg("failed to update todo")
		c.Status(http.StatusInternalServerError)
		return
	}

	c.JSON(http.StatusOK, updatedTodo)
}

func DeleteTodo(c *gin.Context) {
	id := c.Param("id")

	db, ok := c.Get("db")
	if !ok {
		log.Error().Msg("database connection not found")
		c.Status(http.StatusInternalServerError)
		return
	}

	result, err := db.(*sqlx.DB).Exec(deleteTodoSQL, id)
	if err != nil {
		log.Error().Err(err).Msg("failed to delete todo")
		c.Status(http.StatusInternalServerError)
		return
	}

	rowsAffected, err := result.RowsAffected()
	if err != nil {
		log.Error().Err(err).Msg("failed to get rows affected")
		c.Status(http.StatusInternalServerError)
		return
	}

	if rowsAffected == 0 {
		c.Status(http.StatusNotFound)
	} else {
		c.Status(http.StatusOK)
	}
}

