package db

import (
	"database/sql"
	"fmt"
	"log"

	_ "github.com/lib/pq"
)

type Todo struct {
	ID          int    `json:"id"`
	Title       string `json:"title"`
	Completed   bool   `json:"completed"`
	CreatedAt int64  `json:"created_at"`
	UpdatedAt int64  `json:"updated_at"`
}

var db *sql.DB

func Connect(databaseURL string) error {
	var err error
	db, err = sql.Open("postgres", databaseURL)
	if err != nil {
		return fmt.Errorf("error opening database connection: %w", err)
	}

	err = db.Ping()
	if err != nil {
		return fmt.Errorf("error pinging database: %w", err)
	}

	return nil
}

func ListTodos() ([]Todo, error) {
	rows, err := db.Query("SELECT id, title, completed, created_at, updated_at FROM todos")
	if err != nil {
		return nil, fmt.Errorf("error querying database: %w", err)
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var t Todo
		err := rows.Scan(&t.ID, &t.Title, &t.Completed, &t.CreatedAt, &t.UpdatedAt)
		if err != nil {
			return nil, fmt.Errorf("error scanning row: %w", err)
		}
		todos = append(todos, t)
	}

	err = rows.Err()
	if err != nil {
		return nil, fmt.Errorf("error from rows: %w", err)
	}

	return todos, nil
}

func GetTodo(id int) (Todo, error) {
	var t Todo
	err := db.QueryRow("SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = $1", id).Scan(&t.ID, &t.Title, &t.Completed, &t.CreatedAt, &t.UpdatedAt)
	if err != nil {
		if err == sql.ErrNoRows {
			return t, fmt.Errorf("todo with id %d not found", id)
		}
		return t, fmt.Errorf("error querying database: %w", err)
	}

	return t, nil
}

func CreateTodo(title string) (int, error) {
	result, err := db.Exec("INSERT INTO todos (title) VALUES ($1) RETURNING id", title)
	if err != nil {
		return 0, fmt.Errorf("error executing query: %w", err)
	}

	id, err := result.LastInsertId()
	if err != nil {
		return 0, fmt.Errorf("error getting last insert id: %w", err)
	}

	return int(id), nil
}

func UpdateTodo(id int, title string, completed bool) error {
	_, err := db.Exec("UPDATE todos SET title = $1, completed = $2 WHERE id = $3", title, completed, id)
	if err != nil {
		return fmt.Errorf("error executing query: %w", err)
	}

	return nil
}

func DeleteTodo(id int) error {
	result, err := db.Exec("DELETE FROM todos WHERE id = $1", id)
	if err != nil {
		return fmt.Errorf("error executing query: %w", err)
	}

	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return fmt.Errorf("error getting rows affected: %w", err)
	}

	if rowsAffected == 0 {
		return fmt.Errorf("todo with id %d not found", id)
	}

	return nil
}

