    if port == "" {
        port = "8080"
    }

    db, err := sql.Open("postgres", os.Getenv("DATABASE_URL"))
    if err != nil {
        log.Fatal(err)
    }
    defer db.Close()

    todosHandler := handlers.NewTodosHandler(db)

    mux := http.NewServeMux()
    mux.HandleFunc("/todos", todosHandler.List)
    mux.HandleFunc("/todos/", func(w http.ResponseWriter, r *http.Request) {
        params := strings.Split(r.URL.Path, "/")
        id, err := strconv.Atoi(params[len(params)-1])
        if err != nil {
            http.Error(w, "Invalid id", http.StatusBadRequest)
            return
        }

        r.URL.Query().Add("id", fmt.Sprintf("%d", id))
        todosHandler.Get(w, r)
    })
    mux.HandleFunc("/todos/", func(w http.ResponseWriter, r *http.Request) {
        params := strings.Split(r.URL.Path, "/")
        id, err := strconv.Atoi(params[len(params)-1])
        if err != nil {
            http.Error(w, "Invalid id", http.StatusBadRequest)
            return
        }

        r.URL.Query().Add("id", fmt.Sprintf("%d", id))
        todosHandler.Update(w, r)
    })
    mux.HandleFunc("/todos/", func(w http.ResponseWriter, r *http.Request) {
        params := strings.Split(r.URL.Path, "/")
        id, err := strconv.Atoi(params[len(params)-1])
        if err != nil {
            http.Error(w, "Invalid id", http.StatusBadRequest)
            return
        }

        r.URL.Query().Add("id", fmt.Sprintf("%d", id))
        todosHandler.Delete(w, r)
    })

    mux.HandleFunc("/todos/", func(w http.ResponseWriter, r *http.Request) {
        todosHandler.Create(w, r)
    })

    log.Printf("Listening on port %s", port)
    err = http.ListenAndServe(":"+port, mux)
    if err != nil {
        log.Fatal(err)
    }
}

