package handlers

import (
	"context"
	"encoding/json"
	"net/http"

	"github.com/go-chi/chi/v5"
	"yourapp/db"
)

func ListTodos(w http.ResponseWriter, r *http.Request) {
	ctx := context.Background()
	todos, err := db.ListTodos(ctx)
	if err != nil {
		http.Error(w, "internal server error", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todos)
}

func GetTodo(w http.ResponseWriter, r *http.Request) {
	ctx := context.Background()
	id := chi.URLParam(r, "id")
	todo, err := db.GetTodo(ctx, id)
	if err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

func CreateTodo(w http.ResponseWriter, r *http.Request) {
	ctx := context.Background()
	var todo db.Todo
	if err := json.NewDecoder(r.Body).Decode(&todo); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	if todo.Title == "" {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	todo, err = db.CreateTodo(ctx, todo.Title)
	if err != nil {
		http.Error(w, "internal server error", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

func UpdateTodo(w http.ResponseWriter, r *http.Request) {
	ctx := context.Background()
	id := chi.URLParam(r, "id")
	var updates db.Todo
	if err := json.NewDecoder(r.Body).Decode(&updates); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	if updates.Title == "" && !updates.Completed {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	todo, err := db.UpdateTodo(ctx, id, updates.Title, updates.Completed)
	if err != nil {
		http.Error(w, "internal server error", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(todo)
}

func DeleteTodo(w http.ResponseWriter, r *http.Request) {
	ctx := context.Background()
	id := chi.URLParam(r, "id")
	err := db.DeleteTodo(ctx, id)
	if err != nil {
		http.Error(w, "internal server error", http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

