package db

import (
	"database/sql"
	"fmt"
)

type Todo struct {
	ID        int       `db:"id"`
	Title     string    `db:"title"`
	Completed bool      `db:"completed"`
	CreatedAt sql.NullTime
	UpdatedAt sql.NullTime
}

func GetTodos(db *sql.DB) ([]Todo, error) {
	rows, err := db.Query("SELECT id, title, completed, created_at, updated_at FROM todos")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var todos []Todo
	for rows.Next() {
		var todo Todo
		if err := rows.Scan(&todo.ID, &todo.Title, &todo.Completed, &todo.CreatedAt, &todo.UpdatedAt); err != nil {
			return nil, err
		}
		todos = append(todos, todo)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return todos, nil
}

func GetTodo(db *sql.DB, id int) (Todo, error) {
	var todo Todo
	err := db.Get(&todo, "SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = ?", id)
	if err != nil && err == sql.ErrNoRows {
		return Todo{}, fmt.Errorf("todo with id %d not found", id)
	}
	return todo, err
}

func CreateTodo(db *sql.DB, title string) (int, error) {
	result, err := db.Exec("INSERT INTO todos (title, completed) VALUES ($1, false)", title)
	if err != nil {
		return 0, err
	}
	id, err := result.LastInsertId()
	if err != nil {
		return 0, err
	}
	return int(id), nil
}

func UpdateTodo(db *sql.DB, id int, title string) error {
	_, err := db.Exec("UPDATE todos SET title = $1 WHERE id = ?", title, id)
	if err != nil {
		return err
	}
	return nil
}

func DeleteTodo(db *sql.DB, id int) error {
	_, err := db.Exec("DELETE FROM todos WHERE id = ?", id)
	if err != nil {
		return err
	}
	return nil
}

